{"content": "#!/usr/bin/env python3
"""Block-level TileLang design for torch.cat supporting arbitrary concat_dim.

For torch.cat(tensors, dim), the core idea is:
- Flatten all tensors to 2D: [concat_dim_size, sameDimSize]
- Each block owns a contiguous row tile of the output
- For each output row, determine which input tensor it comes from
- Copy the corresponding row from the correct input tensor to output

The tile-level file fills in the T.copy details.
"""

import sys
from pathlib import Path

import tilelang
import tilelang.language as T

_COMMON_DIR = Path(__file__).resolve().parent.parent
if str(_COMMON_DIR) not in sys.path:
    sys.path.insert(0, str(_COMMON_DIR))
from cat_common import pass_configs, select_block_m, kernel_config  # noqa: E402


@tilelang.jit(out_idx=[1], pass_configs=pass_configs)
def cat_1(m0, n_dim, dtype="float32"):
    """1-input cat (identity)."""
    total_m = m0
    block_m, sub_block_m, block_num = kernel_config(total_m)

    def _process_row(r, row_base, row_ub, x0, y_out):
        row_idx = row_base + r
        if row_idx < total_m:
            T.copy(x0[row_idx, :], row_ub)
            T.copy(row_ub, y_out[row_idx, :])

    @T.prim_func
    def main(
        x0: T.Tensor((m0, n_dim), dtype),
        y_out: T.Tensor((total_m, n_dim), dtype),
    ):
        with T.Kernel(block_num, is_npu=True) as (cid, vid):
            bx = cid
            row_base = bx * block_m + vid * sub_block_m
            row_ub = T.alloc_ub((1, n_dim), dtype)

            with T.Scope("V"):
                for r in T.serial(sub_block_m):
                    _process_row(r, row_base, row_ub, x0, y_out)

    return main


@tilelang.jit(out_idx=[2], pass_configs=pass_configs)
def cat_2(m0, m1, n_dim, dtype="float32"):
    """2-input cat along dim0."""
    total_m = m0 + m1
    block_m, sub_block_m, block_num = kernel_config(total_m)

    def _process_row(r, row_base, row_ub, inputs, y_out):
        x0, x1 = inputs
        row_idx = row_base + r
        if row_idx < total_m:
            if row_idx < m0:
                T.copy(x0[row_idx, :], row_ub)
            else:
                T.copy(x1[row_idx - m0, :], row_ub)
            T.copy(row_ub, y_out[row_idx, :])

    @T.prim_func
    def main(
        x0: T.Tensor((m0, n_dim), dtype),
        x1: T.Tensor((m1, n_dim), dtype),
        y_out: T.Tensor((total_m, n_dim), dtype),
    ):
        with T.Kernel(block_num, is_npu=True) as (cid, vid):
            bx = cid
            row_base = bx * block_m + vid * sub_block_m
            row_ub = T.alloc_ub((1, n_dim), dtype)

            with T.Scope("V"):
                for r in T.serial(sub_block_m):
                    _process_row(r, row_base, row_ub, (x0, x1), y_out)

    return main


@tilelang.jit(out_idx=[3], pass_configs=pass_configs)
def cat_3(m0, m1, m2, n_dim, dtype="float32"):
    """3-input cat along dim0."""
    total_m = m0 + m1 + m2
    block_m, sub_block_m, block_num = kernel_config(total_m)
    prefix01 = m0 + m1

    def _process_row(r, row_base, row_ub, inputs, y_out):
        x0, x1, x2 = inputs
        row_idx = row_base + r
        if row_idx < total_m:
            if row_idx < m0:
                T.copy(x0[row_idx, :], row_ub)
            elif row_idx < prefix01:
                T.copy(x1[row_idx - m0, :], row_ub)
            else:
                T.copy(x2[row_idx - prefix01, :], row_ub)
            T.copy(row_ub, y_out[row_idx, :])

    @T.prim_func
    def main(
        x0: T.Tensor((m0, n_dim), dtype),
        x1: T.Tensor((m1, n_dim), dtype),
        x2: T.Tensor((m2, n_dim), dtype),
        y_out: T.Tensor((total_m, n_dim), dtype),
    ):
        with T.Kernel(block_num, is_npu=True) as (cid, vid):
            bx = cid
            row_base = bx * block_m + vid * sub_block_m
            row_ub = T.alloc_ub((1, n_dim), dtype)

            with T.Scope("V"):
                for r in T.serial(sub_block_m):
                    _process_row(r, row_base, row_ub, (x0, x1, x2), y_out)

    return main


@tilelang.jit(out_idx=[4], pass_configs=pass_configs)
def cat_4(*args):
    """4-input cat along dim0."""
    a = [*args, "float32"]
    m0, m1, m2, m3, n_dim, dtype = a[:6]
    total_m = m0 + m1 + m2 + m3
    block_m, sub_block_m, block_num = kernel_config(total_m)
    prefix01 = m0 + m1
    prefix012 = m0 + m1 + m2

    def _process_row(r, row_base, row_ub, inputs, y_out):
        x0, x1, x2, x3 = inputs
        row_idx = row_base + r
        if row_idx < total_m:
            if row_idx < m0:
                T.copy(x0[row_idx, :], row_ub)
            elif row_idx < prefix01:
                T.copy(x1[row_idx - m0, :], row_ub)
            elif row_idx < prefix012:
                T.copy(x2[row_idx - prefix01, :], row_ub)
            else:
                T.copy(x3[row_idx - prefix012, :], row_ub)
            T.copy(row_ub, y_out[row_idx, :])

    @T.prim_func
    def main(
        x0: T.Tensor((m0, n_dim), dtype),
        x1: T.Tensor((m1, n_dim), dtype),
        x2: T.Tensor((m2, n_dim), dtype),
        x3: T.Tensor((m3, n_dim), dtype),
        y_out: T.Tensor((total_m, n_dim), dtype),
    ):
