{"content": "#!/usr/bin/env python3
"""TileLang wrapper for torch.cat supporting arbitrary concat_dim.

The key insight: for torch.cat(tensors, dim), we can flatten all tensors
to 2D by treating the concat dimension as "rows" and all other dimensions
as "columns". Then the problem becomes a simple row-wise concat.
"""

import torch
import torch.nn as nn

import sys
from pathlib import Path

# Set up path for tile_level imports
_design_dir = Path(__file__).resolve().parent / "design" / "tile_level"
if str(_design_dir) not in sys.path:
    sys.path.insert(0, str(_design_dir))

from cat import cat_1, cat_2, cat_3, cat_4, cat_5  # noqa: E402


SUPPORTED_DTYPES = {"float32", "float16", "bfloat16"}


def _validate_and_normalize(inputs, concat_dim):
    """Validate inputs and normalize to 2D for row-wise concat."""
    if not isinstance(inputs, (list, tuple)) or len(inputs) == 0:
        raise ValueError("inputs must be a non-empty list/tuple of tensors")

    first = inputs[0]
    if not isinstance(first, torch.Tensor):
        raise ValueError("All inputs must be torch.Tensor")

    ndim = first.ndim
    if ndim == 0:
        raise ValueError("0D tensors are not supported")

    # Normalize concat_dim
    if concat_dim < 0:
        concat_dim += ndim
    if not (0 <= concat_dim < ndim):
        raise ValueError(f"concat_dim={concat_dim} out of range for {ndim}D tensor")

    dtype = first.dtype
    device = first.device
    dtype_str = str(dtype).split(".")[-1]
    if dtype_str not in SUPPORTED_DTYPES:
        raise ValueError(f"Unsupported dtype: {dtype}")

    # All tensors must have same shape except along concat_dim
    expected_shape = list(first.shape)
    expected_shape[concat_dim] = None  # wildcard

    for i, t in enumerate(inputs):
        if not isinstance(t, torch.Tensor):
            raise ValueError(f"Input {i} is not a torch.Tensor")
        if t.dtype != dtype:
            raise ValueError(f"Input {i} dtype mismatch: {t.dtype} vs {dtype}")
        if t.device != device:
            raise ValueError(f"Input {i} device mismatch: {t.device} vs {device}")
        if t.ndim != ndim:
            raise ValueError(f"Input {i} ndim mismatch: {t.ndim} vs {ndim}")
        t_shape = list(t.shape)
        t_shape[concat_dim] = None
        if t_shape != expected_shape:
            raise ValueError(
                f"Input {i} shape mismatch (except dim {concat_dim}): "
                f"{t.shape} vs {first.shape}"
            )

    # Flatten to 2D: [concat_dim_size, sameDimSize]
    # sameDimSize = product of all dimensions except concat_dim
    same_dim_size = 1
    for d in range(ndim):
        if d != concat_dim:
            same_dim_size *= first.shape[d]

    # Reshape each tensor to [shape[concat_dim], same_dim_size]
    inputs_2d = []
    dim0_sizes = []
    for t in inputs:
        # Move concat_dim to position 0, then flatten the rest
        perm = [concat_dim] + [d for d in range(ndim) if d != concat_dim]
        t_perm = t.permute(perm).contiguous()
        t_2d = t_perm.reshape(t.shape[concat_dim], same_dim_size)
        inputs_2d.append(t_2d)
        dim0_sizes.append(t.shape[concat_dim])

    # Output shape: concat along concat_dim
    output_shape = list(first.shape)
    output_shape[concat_dim] = sum(dim0_sizes)

    return inputs_2d, dim0_sizes, same_dim_size, output_shape, dtype_str, concat_dim


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._kernel_cache = {}

    def forward(self, tensors, dim=0):
        inputs_2d, dim0_sizes, same_dim_size, output_shape, dtype_str, concat_dim = \
            _validate_and_normalize(tensors, dim)

        cache_key = (
            tuple(dim0_sizes),
            same_dim_size,
            dtype_str,
        )
        kernel = self._build_kernel(inputs_2d, same_dim_size, dtype_str)

        # Warmup
        warmed_key = ("warmed", cache_key)
        if not self._kernel_cache.get(warmed_key):
            warm_inputs = [t.clone() for t in inputs_2d]
            _ = self._invoke_kernel(kernel, warm_inputs)
            self._kernel_cache[warmed_key] = True

        y_2d = self._invoke_kernel(kernel, inputs_2d)

        # Reshape back to original ndim with updated concat_dim size
        return y_2d.reshape(output_shape)

    def _build_kernel(self, inputs_2d, same_dim_size, dtype_str):
        dim0_sizes = [int(t.shape[0]) for t in inputs_2d]
        cache_key = (tuple(dim0_sizes), same_dim_size, dtype_str)
        cached = self._kernel_cache.get(cache_key)
        if cached is not None:
            return cached

        input_count = len(inputs_2d)
        if input_count == 1:
            kernel = cat_1(dim0_sizes[0], same_dim_size, dtype=dtype_str)
        elif input_count == 2:
            kernel = cat_2(dim0_sizes[0], dim0_sizes[1], same_dim_size, dtype=dtype_str)
        elif input_count == 3:
            kernel = cat_3(
                dim0_sizes[0], dim0_sizes[1], dim0_sizes[2], same_dim_size, dtype=dtype_str
            )
        elif input_count == 4:
            kernel = cat_4(
                dim0_sizes[0], dim0_sizes[1], dim0_sizes[2], dim0_sizes[3],
                same_dim_size, dtype=dtype_str,
            )
        elif input_count == 5:
            kernel = cat_5(
                dim0_sizes[0], dim0_sizes[1], dim0_sizes[2], dim0_sizes[3], dim0_sizes[4],
                same_dim_size, dtype=dtype_str,
            )
        else:
            raise ValueError(f"Unsupported input count: {input_count}")

        self._kernel_cache[cache_key] = kernel
        return kernel

    def _invoke_kernel(self, kernel, inputs_2d):
        input_count = len(inputs_2d)
        if input_count == 1:
            return kernel(inputs_2d[0])
        if input_count == 2:
            return kernel(inputs_2d[0], inputs_2d[1])
        if input_count == 3:
            return kernel(inputs_2d[0], inputs_2d[1], inputs_2d[2])
        if input_count == 4:
            return kernel(inputs_2d[0], inputs_2d[1], inputs_2d[2], inputs_2d[3])
        return kernel(inputs_2d[0], inputs_2d[1], inputs_2d[2], inputs_2d[3], inputs_2d[4])
