33	inline int32_t CeilDivI32(int32_t a, int32_t b)
34	{
35	    if (b == 0) { return 0; }
36	    return (a + b - 1) / b;
37	}
38	
39	int32_t ChooseBlockM(int32_t totalM)
40	{
41	    for (int32_t candidate : {64, 32, 16, 8, 4, 2}) {
42	        if (totalM >= candidate) {
43	            return candidate;
44	        }
45	    }
46	    return 2;
47	}
48	
49	void CheckInputTensor(const at::Tensor &tensor, const char *name, const at::Tensor &reference)
50	{
51	    TORCH_CHECK(tensor.dim() == 2, name, " must be a 2D tensor");
52	    TORCH_CHECK(tensor.scalar_type() == at::kFloat, name, " must be float32");
53	    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
54	    TORCH_CHECK(tensor.device().type() == reference.device().type(), name, " must be on the same device as x0");
55	    TORCH_CHECK(tensor.sizes()[1] == reference.sizes()[1], name, " must have the same trailing width as x0");
56	}
