{"content": "#!/usr/bin/env python3
"""AscendC wrapper for torch.cat supporting arbitrary concat_dim.

The kernel handles 2D tensors [concat_dim_size, sameDimSize].
The Python wrapper flattens arbitrary-dim tensors to 2D before calling kernel.
"""

import sys
from pathlib import Path

import torch
import torch.nn as nn

_KERNEL_BUILD = Path(__file__).resolve().parent / "kernel" / "build"
_LIB_PATTERN = str(_KERNEL_BUILD / "cat_ext*")

try:
    import cat_ext  # noqa: F401
except ImportError:
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


SUPPORTED_DTYPES = {torch.float16, torch.float32, torch.bfloat16}


def _validate_and_normalize(inputs, concat_dim):
    """Validate inputs and normalize to 2D for row-wise concat."""
    if not isinstance(inputs, (list, tuple)) or len(inputs) == 0:
        raise ValueError("inputs must be a non-empty list/tuple of tensors")

    first = inputs[0]
    if not isinstance(first, torch.Tensor):
        raise ValueError("All inputs must be torch.Tensor")

    ndim = first.ndim
    if ndim == 0:
        raise ValueError("0D tensors are not supported")

    # Normalize concat_dim
    if concat_dim < 0:
        concat_dim += ndim
    if not (0 <= concat_dim < ndim):
        raise ValueError(f"concat_dim={concat_dim} out of range for {ndim}D tensor")

    dtype = first.dtype
    device = first.device
    if dtype not in SUPPORTED_DTYPES:
        raise ValueError(f"Unsupported dtype: {dtype}")

    # All tensors must have same shape except along concat_dim
    expected_shape = list(first.shape)
    expected_shape[concat_dim] = None

    for i, t in enumerate(inputs):
        if not isinstance(t, torch.Tensor):
            raise ValueError(f"Input {i} is not a torch.Tensor")
        if t.dtype != dtype:
            raise ValueError(f"Input {i} dtype mismatch: {t.dtype} vs {dtype}")
        if t.device != device:
            raise ValueError(f"Input {i} device mismatch: {t.device} vs {device}")
        if t.ndim != ndim:
            raise ValueError(f"Input {i} ndim mismatch: {t.ndim} vs {ndim}")
        t_shape = list(t.shape)
        t_shape[concat_dim] = None
        if t_shape != expected_shape:
            raise ValueError(
                f"Input {i} shape mismatch (except dim {concat_dim}): "
                f"{t.shape} vs {first.shape}"
            )

    # Flatten to 2D: [concat_dim_size, sameDimSize]
    same_dim_size = 1
    for d in range(ndim):
        if d != concat_dim:
            same_dim_size *= first.shape[d]

    # Reshape each tensor to [shape[concat_dim], same_dim_size]
    inputs_2d = []
    dim0_sizes = []
    for t in inputs:
        perm = [concat_dim] + [d for d in range(ndim) if d != concat_dim]
        t_perm = t.permute(perm).contiguous()
        t_2d = t_perm.reshape(t.shape[concat_dim], same_dim_size)
        inputs_2d.append(t_2d)
        dim0_sizes.append(t.shape[concat_dim])

